// Work MVP 데이터 관리 훅
import { useState, useEffect, useCallback } from 'react';
import * as store from '../stores/workFirestore';
import * as scheduleStore from '../stores/firestore';
import { useAuth } from '../contexts/AuthContext';
import type { Project, ProjectTask, ProjectTodo } from '../types/work';
import type { ScheduleEvent, TodoItem } from '../types';
import { scheduleEventsToTaskViews, todoItemsToTodoViews, getOriginalId } from '../utils/scheduleAdapter';
import { generateDemoProjects, generateDemoTasks, generateDemoProjectTodos } from '../utils/demoData';

// ===== Projects Hook =====

export function useProjects() {
  const { isDemo } = useAuth();
  const [projects, setProjects] = useState<Project[]>([]);
  const [archivedProjects, setArchivedProjects] = useState<Project[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // 데이터 로드
  const loadProjects = useCallback(async () => {
    setIsLoading(true);
    try {
      if (isDemo) {
        // 데모 모드: 샘플 데이터 사용
        setProjects(generateDemoProjects());
        setArchivedProjects([]);
      } else {
        const [active, archived] = await Promise.all([
          store.getActiveProjects(),
          store.getArchivedProjects(),
        ]);
        setProjects(active);
        setArchivedProjects(archived);
      }
    } catch (error) {
      console.error('Failed to load projects:', error);
    } finally {
      setIsLoading(false);
    }
  }, [isDemo]);

  useEffect(() => {
    loadProjects();
  }, [loadProjects]);

  // 프로젝트 생성
  const createProject = useCallback(async (title: string, color: string = '#a5b4fc', additionalData?: Partial<Project>) => {
    console.log('[useProjects] createProject called:', { title, color, isDemo, additionalData });
    try {
      const now = Date.now();
      const priorityIndex = isDemo ? (projects.length + 1) * -1000 : await store.getNextProjectPriorityIndex();
      console.log('[useProjects] Priority index:', priorityIndex);
      
      const project: Project = {
        id: store.generateId('proj'),
        userId: '', // Firestore에서 자동 설정됨
        title,
        color,
        start_at: additionalData?.start_at ?? null,
        end_at: additionalData?.end_at ?? null,
        due_at: additionalData?.due_at ?? null,
        is_all_day: additionalData?.is_all_day ?? true,
        description: additionalData?.description ?? null,
        url: additionalData?.url ?? null,
        status: 'ACTIVE',
        priority_order_index: priorityIndex,
        created_at: now,
        updated_at: now,
        archived_at: null,
      };
      console.log('[useProjects] Project object created:', project.id);

      if (!isDemo) {
        console.log('[useProjects] Saving to Firestore...');
        await store.saveProject(project);
      }
      console.log('[useProjects] Adding to state');
      setProjects(prev => [project, ...prev]);
      return project;
    } catch (error) {
      console.error('[useProjects] Failed to create project:', error);
      throw error;
    }
  }, [isDemo, projects.length]);

  // 프로젝트 업데이트
  const updateProject = useCallback(async (project: Project) => {
    try {
      // undefined 값을 null로 변환
      const cleaned: Project = {
        ...project,
        description: project.description ?? null,
        url: project.url ?? null,
        updated_at: Date.now(),
      };
      if (!isDemo) {
        await store.saveProject(cleaned);
      }
      setProjects(prev => prev.map(p => p.id === project.id ? cleaned : p));
      return cleaned;
    } catch (error) {
      console.error('Failed to update project:', error);
      throw error;
    }
  }, [isDemo]);

  // 프로젝트 아카이브
  const archiveProject = useCallback(async (projectId: string) => {
    try {
      if (!isDemo) {
        await store.archiveProject(projectId);
      }
      const project = projects.find(p => p.id === projectId);
      if (project) {
        const archived = { ...project, status: 'ARCHIVED' as const, archived_at: Date.now() };
        setProjects(prev => prev.filter(p => p.id !== projectId));
        setArchivedProjects(prev => [archived, ...prev]);
      }
    } catch (error) {
      console.error('Failed to archive project:', error);
      throw error;
    }
  }, [isDemo, projects]);

  // 프로젝트 영구 삭제
  const deleteProjectForever = useCallback(async (projectId: string) => {
    try {
      if (!isDemo) {
        await store.deleteProjectForever(projectId);
      }
      setProjects(prev => prev.filter(p => p.id !== projectId));
      setArchivedProjects(prev => prev.filter(p => p.id !== projectId));
    } catch (error) {
      console.error('Failed to delete project:', error);
      throw error;
    }
  }, [isDemo]);

  // 프로젝트 순서 변경 (드래그 정렬)
  const reorderProjects = useCallback(async (projectIds: string[]) => {
    try {
      // 낙관적 업데이트
      const reordered = projectIds.map((id, index) => {
        const project = projects.find(p => p.id === id);
        return project ? { ...project, priority_order_index: (index + 1) * 1000 } : null;
      }).filter((p): p is Project => p !== null);
      
      setProjects(reordered);
      if (!isDemo) {
        await store.reorderProjects(projectIds);
      }
    } catch (error) {
      console.error('Failed to reorder projects:', error);
      // 실패 시 다시 로드
      loadProjects();
      throw error;
    }
  }, [isDemo, projects, loadProjects]);

  return {
    projects,
    archivedProjects,
    isLoading,
    createProject,
    updateProject,
    archiveProject,
    deleteProjectForever,
    reorderProjects,
    refreshProjects: loadProjects,
  };
}

// ===== Tasks Hook =====

export function useTasks(projectId?: string | null) {
  const { isDemo } = useAuth();
  const [tasks, setTasks] = useState<ProjectTask[]>([]);
  const [doneTasks, setDoneTasks] = useState<ProjectTask[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const loadTasks = useCallback(async () => {
    setIsLoading(true);
    try {
      if (isDemo) {
        // 데모 모드: 샘플 데이터 사용
        const demoTasks = generateDemoTasks();
        const filtered = projectId 
          ? demoTasks.filter(t => t.projectId === projectId)
          : demoTasks;
        setTasks(filtered.filter(t => t.status === 'ACTIVE'));
        setDoneTasks(filtered.filter(t => t.status === 'DONE'));
      } else {
        let active: ProjectTask[];
        let done: ProjectTask[];

        if (projectId) {
          const allTasks = await store.getTasksByProject(projectId);
          active = allTasks.filter(t => t.status === 'ACTIVE');
          done = allTasks.filter(t => t.status === 'DONE');
        } else {
          [active, done] = await Promise.all([
            store.getActiveTasks(),
            store.getDoneTasks(),
          ]);
        }

        setTasks(active);
        setDoneTasks(done);
      }
    } catch (error) {
      console.error('Failed to load tasks:', error);
    } finally {
      setIsLoading(false);
    }
  }, [isDemo, projectId]);

  useEffect(() => {
    loadTasks();
  }, [loadTasks]);

  const createTask = useCallback(async (title: string, taskProjectId: string | null = null, additionalData?: Partial<ProjectTask>) => {
    try {
      const now = Date.now();
      const priorityIndex = isDemo ? (tasks.length + 1) * -1000 : await store.getNextTaskPriorityIndex();

      const task: ProjectTask = {
        id: store.generateId('task'),
        projectId: taskProjectId,
        title,
        start_at: additionalData?.start_at ?? null,
        end_at: additionalData?.end_at ?? null,
        due_at: additionalData?.due_at ?? null,
        is_all_day: additionalData?.is_all_day ?? true,
        description: additionalData?.description ?? null,
        url: additionalData?.url ?? null,
        status: 'ACTIVE',
        completed_at: null,
        priority_order_index: priorityIndex,
        unscheduled_order_index: 0,
        created_at: now,
        updated_at: now,
      };

      if (!isDemo) {
        await store.saveTask(task);
      }
      setTasks(prev => [task, ...prev]);
      return task;
    } catch (error) {
      console.error('Failed to create task:', error);
      throw error;
    }
  }, [isDemo, tasks.length]);

  const updateTask = useCallback(async (task: ProjectTask) => {
    try {
      // undefined 값을 null로 변환
      const cleaned: ProjectTask = {
        ...task,
        description: task.description ?? null,
        url: task.url ?? null,
        updated_at: Date.now(),
      };
      if (!isDemo) {
        await store.saveTask(cleaned);
      }
      setTasks(prev => prev.map(t => t.id === task.id ? cleaned : t));
      return cleaned;
    } catch (error) {
      console.error('Failed to update task:', error);
      throw error;
    }
  }, [isDemo]);

  const completeTask = useCallback(async (taskId: string) => {
    try {
      if (!isDemo) {
        await store.completeTask(taskId);
      }
      const task = tasks.find(t => t.id === taskId);
      if (task) {
        const completed = { ...task, status: 'DONE' as const, completed_at: Date.now() };
        setTasks(prev => prev.filter(t => t.id !== taskId));
        setDoneTasks(prev => [completed, ...prev]);
      }
    } catch (error) {
      console.error('Failed to complete task:', error);
      throw error;
    }
  }, [isDemo, tasks]);

  const undoCompleteTask = useCallback(async (taskId: string) => {
    try {
      if (!isDemo) {
        await store.undoCompleteTask(taskId);
      }
      const task = doneTasks.find(t => t.id === taskId);
      if (task) {
        const active = { ...task, status: 'ACTIVE' as const, completed_at: null };
        setDoneTasks(prev => prev.filter(t => t.id !== taskId));
        setTasks(prev => [active, ...prev]);
      }
    } catch (error) {
      console.error('Failed to undo complete task:', error);
      throw error;
    }
  }, [isDemo, doneTasks]);

  const deleteTask = useCallback(async (taskId: string) => {
    try {
      if (!isDemo) {
        await store.deleteTask(taskId);
      }
      setTasks(prev => prev.filter(t => t.id !== taskId));
      setDoneTasks(prev => prev.filter(t => t.id !== taskId));
    } catch (error) {
      console.error('Failed to delete task:', error);
      throw error;
    }
  }, [isDemo]);

  const reorderTasks = useCallback(async (taskIds: string[]) => {
    try {
      const reordered = taskIds.map((id, index) => {
        const task = tasks.find(t => t.id === id);
        return task ? { ...task, priority_order_index: (index + 1) * 1000 } : null;
      }).filter((t): t is ProjectTask => t !== null);

      setTasks(reordered);
      if (!isDemo) {
        await store.reorderTasks(taskIds);
      }
    } catch (error) {
      console.error('Failed to reorder tasks:', error);
      loadTasks();
      throw error;
    }
  }, [isDemo, tasks, loadTasks]);

  return {
    tasks,
    doneTasks,
    isLoading,
    createTask,
    updateTask,
    completeTask,
    undoCompleteTask,
    deleteTask,
    reorderTasks,
    refreshTasks: loadTasks,
  };
}

// ===== Todos Hook =====

export function useProjectTodos(taskId?: string | null) {
  const { isDemo } = useAuth();
  const [todos, setTodos] = useState<ProjectTodo[]>([]);
  const [doneTodos, setDoneTodos] = useState<ProjectTodo[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const loadTodos = useCallback(async () => {
    setIsLoading(true);
    try {
      if (isDemo) {
        // 데모 모드: 샘플 데이터 사용
        const demoTodos = generateDemoProjectTodos();
        const filtered = taskId 
          ? demoTodos.filter(t => t.taskId === taskId)
          : demoTodos;
        setTodos(filtered.filter(t => !t.is_done));
        setDoneTodos(filtered.filter(t => t.is_done));
      } else {
        let active: ProjectTodo[];
        let done: ProjectTodo[];

        if (taskId) {
          const allTodos = await store.getTodosByTask(taskId);
          active = allTodos.filter(t => !t.is_done);
          done = allTodos.filter(t => t.is_done);
        } else {
          [active, done] = await Promise.all([
            store.getActiveTodos(),
            store.getDoneTodos(),
          ]);
        }

        setTodos(active);
        setDoneTodos(done);
      }
    } catch (error) {
      console.error('Failed to load todos:', error);
    } finally {
      setIsLoading(false);
    }
  }, [isDemo, taskId]);

  useEffect(() => {
    loadTodos();
  }, [loadTodos]);

  const createTodo = useCallback(async (
    content: string,
    todoTaskId: string | null = null,
    start_at: string | null = null,
    end_at: string | null = null,
    due_at: string | null = null,
    is_all_day: boolean = true,
    show_in_calendar: boolean = false,
    additionalData?: Partial<ProjectTodo>
  ) => {
    try {
      const now = Date.now();
      const priorityIndex = isDemo ? (todos.length + 1) * -1000 : await store.getNextTodoPriorityIndex(todoTaskId);

      const todo: ProjectTodo = {
        id: store.generateId('todo'),
        taskId: todoTaskId,
        content,
        start_at,
        end_at,
        due_at,
        is_all_day,
        is_done: additionalData?.is_done ?? false,
        completed_at: additionalData?.completed_at ?? null,
        priority_order_index: priorityIndex,
        unscheduled_order_index: 0,
        show_in_calendar,
        note: additionalData?.note ?? null,
        url: additionalData?.url ?? null,
        status: additionalData?.status ?? 'active',
        created_at: now,
        updated_at: now,
      };

      if (!isDemo) {
        await store.saveProjectTodo(todo);
      }
      setTodos(prev => [todo, ...prev]);
      return todo;
    } catch (error) {
      console.error('Failed to create todo:', error);
      throw error;
    }
  }, [isDemo, todos.length]);

  const updateTodo = useCallback(async (todo: ProjectTodo) => {
    try {
      // undefined 값을 null로 변환
      const cleaned: ProjectTodo = {
        ...todo,
        note: todo.note ?? null,
        url: todo.url ?? null,
        updated_at: Date.now(),
      };
      if (!isDemo) {
        await store.saveProjectTodo(cleaned);
      }
      
      // 완료 상태에 따라 적절한 리스트로 이동
      if (cleaned.is_done) {
        // 완료된 항목 -> doneTodos로 이동
        setTodos(prev => prev.filter(t => t.id !== todo.id));
        setDoneTodos(prev => {
          const exists = prev.some(t => t.id === todo.id);
          if (exists) {
            return prev.map(t => t.id === todo.id ? cleaned : t);
          }
          return [cleaned, ...prev];
        });
      } else {
        // 진행중/연기/취소 -> todos로 이동
        setDoneTodos(prev => prev.filter(t => t.id !== todo.id));
        setTodos(prev => {
          const exists = prev.some(t => t.id === todo.id);
          if (exists) {
            return prev.map(t => t.id === todo.id ? cleaned : t);
          }
          return [cleaned, ...prev];
        });
      }
      
      return cleaned;
    } catch (error) {
      console.error('Failed to update todo:', error);
      throw error;
    }
  }, [isDemo]);

  // 상태 순환: active -> done -> delayed -> cancelled -> active
  const STATUS_CYCLE: ('active' | 'done' | 'delayed' | 'cancelled')[] = ['active', 'done', 'delayed', 'cancelled'];

  const cycleTodoStatus = useCallback(async (todoId: string) => {
    try {
      // todos와 doneTodos 양쪽에서 찾기
      let todo = todos.find(t => t.id === todoId);
      if (!todo) {
        todo = doneTodos.find(t => t.id === todoId);
      }
      if (!todo) return;

      // 현재 상태 확인 및 다음 상태 계산
      const currentStatus = todo.status || (todo.is_done ? 'done' : 'active');
      const currentIndex = STATUS_CYCLE.indexOf(currentStatus);
      const nextStatus = STATUS_CYCLE[(currentIndex + 1) % STATUS_CYCLE.length];
      
      const updated: ProjectTodo = {
        ...todo,
        status: nextStatus,
        is_done: nextStatus === 'done',
        completed_at: nextStatus === 'done' ? Date.now() : null,
        updated_at: Date.now(),
      };

      if (!isDemo) {
        await store.saveProjectTodo(updated);
      }

      // 상태에 따라 적절한 리스트로 이동
      // 현재 항목이 어느 리스트에 있는지 확인
      const isInTodos = todos.some(t => t.id === todoId);
      const isInDoneTodos = doneTodos.some(t => t.id === todoId);
      
      if (nextStatus === 'done') {
        if (isInTodos) {
          // todos에 있던 항목: 위치 유지하며 상태만 업데이트 (UI에서는 recentlyCompleted로 유지)
          setTodos(prev => prev.map(t => t.id === todoId ? updated : t));
        }
        if (isInDoneTodos) {
          // doneTodos에 있던 항목: 상태만 업데이트
          setDoneTodos(prev => prev.map(t => t.id === todoId ? updated : t));
        }
      } else {
        // active/delayed/cancelled로 변경
        if (isInDoneTodos) {
          // doneTodos에서 todos로 이동
          setDoneTodos(prev => prev.filter(t => t.id !== todoId));
          setTodos(prev => [updated, ...prev]);
        } else if (isInTodos) {
          // todos에 있던 항목: 위치 유지하며 상태만 업데이트
          setTodos(prev => prev.map(t => t.id === todoId ? updated : t));
        }
      }
    } catch (error) {
      console.error('Failed to cycle todo status:', error);
      throw error;
    }
  }, [isDemo, todos, doneTodos]);

  // 하위 호환성을 위해 기존 함수명 유지
  const completeTodo = cycleTodoStatus;

  const undoCompleteTodo = useCallback(async (todoId: string) => {
    try {
      const todo = doneTodos.find(t => t.id === todoId);
      if (!todo) return;
      
      const updated: ProjectTodo = {
        ...todo,
        status: 'active',
        is_done: false,
        completed_at: null,
        updated_at: Date.now(),
      };

      if (!isDemo) {
        await store.saveProjectTodo(updated);
      }
      
      setDoneTodos(prev => prev.filter(t => t.id !== todoId));
      setTodos(prev => [updated, ...prev]);
    } catch (error) {
      console.error('Failed to undo complete todo:', error);
      throw error;
    }
  }, [isDemo, doneTodos]);

  const deleteTodo = useCallback(async (todoId: string) => {
    try {
      if (!isDemo) {
        await store.deleteProjectTodo(todoId);
      }
      setTodos(prev => prev.filter(t => t.id !== todoId));
      setDoneTodos(prev => prev.filter(t => t.id !== todoId));
    } catch (error) {
      console.error('Failed to delete todo:', error);
      throw error;
    }
  }, [isDemo]);

  const reorderTodos = useCallback(async (todoIds: string[]) => {
    try {
      const reordered = todoIds.map((id, index) => {
        const todo = todos.find(t => t.id === id);
        return todo ? { ...todo, priority_order_index: (index + 1) * 1000 } : null;
      }).filter((t): t is ProjectTodo => t !== null);

      setTodos(reordered);
      if (!isDemo) {
        await store.reorderTodos(todoIds);
      }
    } catch (error) {
      console.error('Failed to reorder todos:', error);
      loadTodos();
      throw error;
    }
  }, [isDemo, todos, loadTodos]);

  return {
    todos,
    doneTodos,
    isLoading,
    createTodo,
    updateTodo,
    completeTodo,
    undoCompleteTodo,
    deleteTodo,
    reorderTodos,
    refreshTodos: loadTodos,
  };
}

// ===== 기존 일정 데이터 Hook =====

export type ScheduleTaskView = ProjectTask & { isReadOnly: true; sourceType: 'schedule' };
export type ScheduleTodoView = ProjectTodo & { isReadOnly: true; sourceType: 'todo' };

export function useScheduleEvents() {
  const { isDemo } = useAuth();
  const [events, setEvents] = useState<ScheduleEvent[]>([]);
  const [taskViews, setTaskViews] = useState<ScheduleTaskView[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const loadEvents = useCallback(async () => {
    setIsLoading(true);
    try {
      if (isDemo) {
        // 데모 모드에서는 빈 배열
        setEvents([]);
        setTaskViews([]);
      } else {
        const allEvents = await scheduleStore.getEvents();
        setEvents(allEvents);
        setTaskViews(scheduleEventsToTaskViews(allEvents));
      }
    } catch (error) {
      console.error('Failed to load schedule events:', error);
    } finally {
      setIsLoading(false);
    }
  }, [isDemo]);

  useEffect(() => {
    loadEvents();
  }, [loadEvents]);

  // 이벤트 업데이트
  const updateEvent = useCallback(async (event: ScheduleEvent) => {
    if (isDemo) return;
    try {
      await scheduleStore.saveEvent(event);
      // 간단하게 이벤트 목록 업데이트 후 taskViews 재생성
      setEvents(prev => {
        const updated = prev.map(e => e.id === event.id ? event : e);
        setTaskViews(scheduleEventsToTaskViews(updated));
        return updated;
      });
    } catch (error) {
      console.error('Failed to update event:', error);
      throw error;
    }
  }, [isDemo]);

  // 이벤트 삭제
  const deleteEvent = useCallback(async (eventId: string) => {
    if (isDemo) return;
    try {
      await scheduleStore.deleteEvent(eventId);
      setEvents(prev => prev.filter(e => e.id !== eventId));
      setTaskViews(prev => prev.filter(t => t.id !== `schedule-${eventId}`));
    } catch (error) {
      console.error('Failed to delete event:', error);
      throw error;
    }
  }, [isDemo]);

  // 활성/완료 분리
  const activeTaskViews = taskViews.filter(t => t.status === 'ACTIVE');
  const doneTaskViews = taskViews.filter(t => t.status === 'DONE');

  return {
    events,
    taskViews,
    activeTaskViews,
    doneTaskViews,
    isLoading,
    updateEvent,
    deleteEvent,
    refreshEvents: loadEvents,
  };
}

export function useScheduleTodos() {
  const { isDemo } = useAuth();
  const [todos, setTodos] = useState<TodoItem[]>([]);
  const [todoViews, setTodoViews] = useState<ScheduleTodoView[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const loadTodos = useCallback(async () => {
    setIsLoading(true);
    try {
      if (isDemo) {
        // 데모 모드에서는 빈 배열
        setTodos([]);
        setTodoViews([]);
      } else {
        const allTodos = await scheduleStore.getTodos();
        setTodos(allTodos);
        setTodoViews(todoItemsToTodoViews(allTodos));
      }
    } catch (error) {
      console.error('Failed to load schedule todos:', error);
    } finally {
      setIsLoading(false);
    }
  }, [isDemo]);

  useEffect(() => {
    loadTodos();
  }, [loadTodos]);

  // 삭제 함수
  const deleteTodo = useCallback(async (todoId: string) => {
    if (isDemo) return;
    try {
      // todoId가 'todoitem_xxx' 형태면 원본 ID 추출
      const originalId = getOriginalId(todoId);
      await scheduleStore.deleteTodo(originalId);
      setTodos(prev => prev.filter(t => t.id !== originalId));
      setTodoViews(prev => prev.filter(t => t.id !== todoId));
    } catch (error) {
      console.error('Failed to delete schedule todo:', error);
      throw error;
    }
  }, [isDemo]);

  // 상태 순환: active -> done -> delayed -> cancelled -> active
  const STATUS_CYCLE = ['active', 'done', 'delayed', 'cancelled'] as const;
  
  // 완료 함수 (상태 순환)
  const completeTodo = useCallback(async (todoViewId: string) => {
    if (isDemo) return;
    try {
      // todoViewId가 'todoitem_xxx' 형태면 원본 ID 추출
      const originalId = getOriginalId(todoViewId);
      const originalTodo = todos.find(t => t.id === originalId);
      if (!originalTodo) return;
      
      // 현재 상태에서 다음 상태로 순환
      const currentStatus = originalTodo.status || 'active';
      const currentIndex = STATUS_CYCLE.indexOf(currentStatus as typeof STATUS_CYCLE[number]);
      const nextStatus = STATUS_CYCLE[(currentIndex + 1) % STATUS_CYCLE.length];
      
      const updatedTodo: TodoItem = {
        ...originalTodo,
        status: nextStatus,
        updatedAt: Date.now(),
      };
      await scheduleStore.saveTodo(updatedTodo);
      setTodos(prev => prev.map(t => t.id === originalId ? updatedTodo : t));
      // 일정 Todo는 상태만 변경하고 is_done은 변경하지 않음 (리스트 이동 방지)
      // 탭 전환/새로고침 시에만 is_done 기준으로 분류됨
      setTodoViews(prev => prev.map(t => t.id === todoViewId ? { 
        ...t, 
        status: nextStatus,
        // is_done과 completed_at는 변경하지 않음 - 위치 유지
      } : t));
    } catch (error) {
      console.error('Failed to cycle schedule todo status:', error);
      throw error;
    }
  }, [isDemo, todos]);

  // 완료 취소 함수 (active로 되돌림)
  const undoCompleteTodo = useCallback(async (todoViewId: string) => {
    if (isDemo) return;
    try {
      // todoViewId가 'todoitem_xxx' 형태면 원본 ID 추출
      const originalId = getOriginalId(todoViewId);
      const originalTodo = todos.find(t => t.id === originalId);
      if (!originalTodo) return;
      
      const updatedTodo: TodoItem = {
        ...originalTodo,
        status: 'active',
        updatedAt: Date.now(),
      };
      await scheduleStore.saveTodo(updatedTodo);
      setTodos(prev => prev.map(t => t.id === originalId ? updatedTodo : t));
      setTodoViews(prev => prev.map(t => t.id === todoViewId ? { ...t, is_done: false, completed_at: null, status: 'active' } : t));
    } catch (error) {
      console.error('Failed to undo complete schedule todo:', error);
      throw error;
    }
  }, [isDemo, todos]);

  // 일정 Todo 업데이트 함수
  const updateTodo = useCallback(async (todoViewId: string, updates: Partial<TodoItem>) => {
    if (isDemo) return;
    try {
      const originalId = getOriginalId(todoViewId);
      const originalTodo = todos.find(t => t.id === originalId);
      if (!originalTodo) return;
      
      const updatedTodo: TodoItem = {
        ...originalTodo,
        ...updates,
        id: originalId, // ID는 원본 유지
        updatedAt: Date.now(),
      };
      await scheduleStore.saveTodo(updatedTodo);
      setTodos(prev => prev.map(t => t.id === originalId ? updatedTodo : t));
      
      // View 업데이트
      setTodoViews(prev => prev.map(t => {
        if (t.id !== todoViewId) return t;
        return {
          ...t,
          content: updates.title ?? t.content,
          start_at: updates.date ? `${updates.date}T00:00:00` : t.start_at,
          end_at: updates.date ? `${updates.date}T23:59:00` : t.end_at,
          status: updates.status ?? t.status,
        };
      }));
    } catch (error) {
      console.error('Failed to update schedule todo:', error);
      throw error;
    }
  }, [isDemo, todos]);

  // 활성/완료 분리
  const activeTodoViews = todoViews.filter(t => !t.is_done);
  const doneTodoViews = todoViews.filter(t => t.is_done);

  return {
    todos,
    todoViews,
    activeTodoViews,
    doneTodoViews,
    isLoading,
    deleteTodo,
    completeTodo,
    undoCompleteTodo,
    updateTodo,
    refreshTodos: loadTodos,
  };
}
